// The player's catalogue tooling (docs/plan.md Phase 54 item 2;
// docs/verify-player.md, "The player's words"). Two generated files,
// both committed, both rewritten by `npm run i18n` and by every build,
// and both checked by `npm test` (scripts/i18n.test.mjs), which fails
// while either is stale:
//
// - player/locales/messages.pot, the translators' template, from the
//   English catalogue (src/i18n/en.ts): one entry per message, `msgctxt`
//   its key, `msgid` its English, and a `#.` comment (the entry's doc
//   comment in en.ts, required, plus its placeholders). A plural message
//   becomes one entry per CLDR category, `msgctxt` `key#category`. The
//   template carries English's categories (`one`, `other`); a language
//   needing others (`few`, `many`, `two`, `zero`) adds an entry for each
//   of its own, its `msgid` the English `other`.
// - src/i18n/locales.generated.ts, every player/locales/<tag>.po
//   compiled to the runtime catalogue the bundle carries (the tag is the
//   file's name). An empty `msgstr` is untranslated (English serves). A
//   fuzzy entry is used. An entry with an unknown key, a plural category
//   on a plain message or none on a plural one, or placeholders not the
//   English's is left out and reported.
//
// Run: `node scripts/i18n.mjs` (writes both, prints any problem) or
// `node scripts/i18n.mjs --check` (writes nothing; exit 1 if stale).

import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { basename, join } from "node:path";
import { fileURLToPath } from "node:url";
import { EN } from "../src/i18n/en.ts";
import { parsePo, poField } from "./po.mjs";

const playerDir = fileURLToPath(new URL("..", import.meta.url));
export const EN_SOURCE = join(playerDir, "src", "i18n", "en.ts");
export const LOCALES_DIR = join(playerDir, "locales");
export const POT_FILE = join(LOCALES_DIR, "messages.pot");
export const GENERATED_FILE = join(
  playerDir,
  "src",
  "i18n",
  "locales.generated.ts",
);

/** The `{name}` placeholders in `text`, in order, each once. */
export function placeholdersOf(text) {
  return [...new Set(text.match(/\{[A-Za-z0-9_]+\}/g) ?? [])];
}

/** Every placeholder of a message (all its plural texts). */
function messagePlaceholders(message) {
  const texts =
    typeof message === "string" ? [message] : Object.values(message);
  return [...new Set(texts.flatMap(placeholdersOf))];
}

/**
 * The doc comment above each key of en.ts (`source`), whitespace and
 * leading stars collapsed: key -> note.
 */
export function readNotes(source) {
  const notes = {};
  const entry = /\/\*\*([\s\S]*?)\*\/\s*\n\s*"([^"]+)":/g;
  for (const [, body, key] of source.matchAll(entry)) {
    notes[key] = body
      .split("\n")
      .map((line) => line.replace(/^\s*\*?\s?/, "").trim())
      .filter((line) => line !== "")
      .join(" ");
  }
  return notes;
}

const POT_HEADER = [
  "# The Kinetic player's own words: the template for a translation.",
  "# Generated by player/scripts/i18n.mjs from player/src/i18n/en.ts; do not",
  "# edit. Copy it to <tag>.po (a BCP 47 tag: de, pt-BR, zh-Hans), fill each",
  "# msgstr and keep every {placeholder} as written.",
  "#",
  "# msgctxt is the message's key. A plural message has one entry per plural",
  '# category, msgctxt "key#category"; this template has English\'s two',
  "# (one, other). A language with other CLDR categories (zero, two, few,",
  "# many) adds an entry for each of its own, msgctxt key#few and so on.",
  'msgid ""',
  'msgstr ""',
  '"Project-Id-Version: Kinetic player\\n"',
  '"MIME-Version: 1.0\\n"',
  '"Content-Type: text/plain; charset=UTF-8\\n"',
  '"Content-Transfer-Encoding: 8bit\\n"',
];

/** The template's text for the catalogue `en`, its notes from `notes`. */
export function buildPot(
  en = EN,
  notes = readNotes(readFileSync(EN_SOURCE, "utf8")),
) {
  const blocks = [POT_HEADER.join("\n")];
  for (const [key, message] of Object.entries(en)) {
    const note = notes[key];
    if (note === undefined) {
      throw new Error(`src/i18n/en.ts: "${key}" has no doc comment`);
    }
    const holders = messagePlaceholders(message);
    const comments = [`#. ${note}`];
    if (holders.length > 0) {
      comments.push(`#. Placeholders: ${holders.join(", ")}.`);
    }
    if (typeof message === "string") {
      blocks.push(
        [
          ...comments,
          poField("msgctxt", key),
          poField("msgid", message),
          'msgstr ""',
        ].join("\n"),
      );
      continue;
    }
    for (const [category, text] of Object.entries(message)) {
      blocks.push(
        [
          ...comments,
          `#. Plural form "${category}" (CLDR), chosen by {count}.`,
          poField("msgctxt", `${key}#${category}`),
          poField("msgid", text),
          'msgstr ""',
        ].join("\n"),
      );
    }
  }
  return `${blocks.join("\n\n")}\n`;
}

const CATEGORIES = new Set(["zero", "one", "two", "few", "many", "other"]);

/**
 * One PO file's text compiled against `en`: `{ catalogue, problems }`.
 * `catalogue` maps keys (in en's order) to a string or a plural object;
 * `problems` names each entry left out and why.
 */
export function compilePo(text, en = EN, name = "<po>") {
  const { entries } = parsePo(text);
  const found = new Map();
  const problems = [];
  for (const entry of entries) {
    const where = `${name}:${entry.line}`;
    if (entry.idPlural !== undefined) {
      problems.push(
        `${where}: msgid_plural is not used (msgctxt key#category is)`,
      );
      continue;
    }
    const str = entry.str ?? "";
    if (str === "") continue; // untranslated: English serves
    if (entry.context === undefined) {
      problems.push(`${where}: no msgctxt (the message's key)`);
      continue;
    }
    const [key, category, ...rest] = entry.context.split("#");
    const english = en[key];
    if (english === undefined || rest.length > 0) {
      problems.push(`${where}: unknown key "${entry.context}"`);
      continue;
    }
    const plural = typeof english !== "string";
    if (plural !== (category !== undefined)) {
      problems.push(
        plural
          ? `${where}: "${key}" is a plural message: msgctxt "${key}#<category>"`
          : `${where}: "${key}" is not a plural message`,
      );
      continue;
    }
    if (plural && !CATEGORIES.has(category)) {
      problems.push(`${where}: "${category}" is no plural category`);
      continue;
    }
    const allowed = new Set(messagePlaceholders(english));
    const used = placeholdersOf(str);
    const unknown = used.filter((p) => !allowed.has(p));
    const missing = plural ? [] : [...allowed].filter((p) => !used.includes(p));
    if (unknown.length > 0 || missing.length > 0) {
      problems.push(
        `${where}: "${entry.context}" placeholders differ from the English (${[
          ...unknown.map((p) => `extra ${p}`),
          ...missing.map((p) => `missing ${p}`),
        ].join(", ")})`,
      );
      continue;
    }
    if (plural) {
      const forms = found.get(key) ?? {};
      forms[category] = str;
      found.set(key, forms);
    } else {
      found.set(key, str);
    }
  }
  const catalogue = {};
  for (const key of Object.keys(en)) {
    const value = found.get(key);
    if (value === undefined) continue;
    if (typeof value !== "string" && value.other === undefined) {
      problems.push(`${name}: "${key}" has no "other" form; left out`);
      continue;
    }
    catalogue[key] = value;
  }
  return { catalogue, problems };
}

/** The tags of the PO files in `dir` (`<tag>.po`), sorted. */
export function localeTags(dir = LOCALES_DIR) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((file) => file.endsWith(".po"))
    .map((file) => basename(file, ".po"))
    .sort();
}

/** The generated module's text for `locales` (tag -> catalogue). */
export function buildModule(locales) {
  const body =
    Object.keys(locales).length === 0 ? "{}" : JSON.stringify(locales, null, 2);
  return [
    "// Generated by scripts/i18n.mjs from player/locales/<tag>.po: do not edit.",
    "// `npm run i18n` (and every build) rewrites it; npm test fails while it",
    '// is stale (docs/verify-player.md, "The player\'s words").',
    'import type { Catalogue } from "./catalogue.ts";',
    "",
    `export const LOCALES: Readonly<Record<string, Catalogue>> = ${body};`,
    "",
  ].join("\n");
}

/**
 * Both generated files' text from the sources now: `{ pot, module,
 * problems, tags }`.
 */
export function generateI18n(dir = LOCALES_DIR) {
  const pot = buildPot();
  const locales = {};
  const problems = [];
  const tags = localeTags(dir);
  for (const tag of tags) {
    const file = join(dir, `${tag}.po`);
    const compiled = compilePo(readFileSync(file, "utf8"), EN, `${tag}.po`);
    locales[tag] = compiled.catalogue;
    problems.push(...compiled.problems);
  }
  return { pot, module: buildModule(locales), problems, tags };
}

function readOr(file) {
  return existsSync(file) ? readFileSync(file, "utf8") : null;
}

/** Writes whichever generated file is stale; returns the generation. */
export function writeI18n() {
  const generated = generateI18n();
  if (readOr(POT_FILE) !== generated.pot)
    writeFileSync(POT_FILE, generated.pot);
  if (readOr(GENERATED_FILE) !== generated.module) {
    writeFileSync(GENERATED_FILE, generated.module);
  }
  return generated;
}

/** The generated files that differ from what the sources give now. */
export function staleI18n() {
  const generated = generateI18n();
  const stale = [];
  if (readOr(POT_FILE) !== generated.pot) stale.push(POT_FILE);
  if (readOr(GENERATED_FILE) !== generated.module) stale.push(GENERATED_FILE);
  return stale;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (process.argv.includes("--check")) {
    const stale = staleI18n();
    for (const file of stale) console.error(`stale: ${file}`);
    process.exit(stale.length === 0 ? 0 : 1);
  }
  const { problems, tags } = writeI18n();
  for (const problem of problems) console.warn(problem);
  console.log(
    `${Object.keys(EN).length} messages; messages.pot and ${tags.length} language(s) written`,
  );
}
